def is_winning_final(F, max_k=50):
    max_n = 300
    W = [set() for _ in range(max_k + 1)]
    for n in range(1, max_n + 1):
        if F % n == 0 or n % F == 0:
            W[0].add(n)

    M = None
    for m in range(max_n, 0, -1):
        all_ge = True
        for n in range(m, max_n + 1):
            if n not in W[0]:
                all_ge = False
                break
        if all_ge:
            M = m
            break

    for k in range(1, max_k + 1):
        W[k] = set(W[k-1])
        if M is not None:
            # If W[k-1] contains all n >= M, then W[k] contains all n.
            # Because for any n, we can choose d = n * M.
            # Then d-1 = n*M-1, d+1 = n*M+1.
            # If n >= 2, d-1 >= 2M-1. If M >= 2, 2M-1 >= M.
            # If M=1, W[k-1] contains all n >= 1, so W[k] contains all n.
            # If M > 1, we need d-1 >= M and d+1 >= M.
            # For n=1, we can choose d=M+1. d-1=M, d+1=M+2. Both >= M.
            # So all n are in W[k].
            for n in range(1, max_n + 1):
                W[k].add(n)
            M = 1
            return True

        valid_ds = []
        for d in range(2, max_n + 2):
            if (d-1 in W[k-1] and d+1 in W[k-1]):
                valid_ds.append(d)

        for d in valid_ds:
            for i in range(1, int(d**0.5) + 1):
                if d % i == 0:
                    if i <= max_n: W[k].add(i)
                    if d // i <= max_n: W[k].add(d // i)
            for n in range(d, max_n + 1, d):
                W[k].add(n)

        M = None
        for m in range(max_n, 0, -1):
            all_ge = True
            for n in range(m, max_n + 1):
                if n not in W[k]:
                    all_ge = False
                    break
            if all_ge:
                M = m
                break
    return M is not None or len(W[max_k]) == max_n

