def solve_F(F, limit=200):
    d = [float('inf')] * (limit + 1)
    d[F] = 0
    for _ in range(limit + 1):
        changed = False
        for x in range(1, limit + 1):
            if x == F: continue
            best = float('inf')
            for div in range(2, limit + 1):
                if x % div == 0 or div % x == 0:
                    v1 = d[div-1] if div-1 >= 1 else float('inf')
                    v2 = d[div+1] if div+1 <= limit else float('inf')
                    if v1 != float('inf') and v2 != float('inf'):
                        best = min(best, max(v1, v2))
            if d[x] == float('inf') and best != float('inf'):
                d[x] = 1 + best
                changed = True
        if not changed: break
    return d

for F in range(2, 20):
    res = solve_F(F)
    if all(v != float('inf') for v in res):
        print(f"F={F} works")
    else:
        print(f"F={F} does not work")

def check_final_version(F, max_turns=50):
    # V_0 = {F}
    # V_1 = {X : F|X or X|F, X > 1}
    # V_k = {X : exists d in DivMult(X), d > 1, d-1 in V_{k-1} and d+1 in V_{k-1}}
    # But wait, I also need to include V_{k-1} in V_k.
    V = {F}
    V = set(V)
    # Wait, let's re-trace.
    # V_0 = {F}
    # V_1 = {X : F|X or X|F, X > 1}
    # For k=2 to 50:
    # V_k = V_{k-1} \cup {X : exists d in DivMult(X), d > 1, d-1 in V_{k-1} and d+1 in V_{k-1}}

    # Wait, if V_k contains all numbers, then F is a solution.
    # But how to check if V_k contains all numbers?
