def solve_with_forced_rule(F):
    M = 150
    d = [float('inf')] * (M + 2)
    d[F] = 0
    for _ in range(M):
        new_d = [float('inf')] * (M + 2)
        new_d[F] = 0
        for x in range(2, M + 1):
            if x == F: continue
            min_max_d = float('inf')
            divs = []
            for i in range(1, int(x**0.5) + 1):
                if x % i == 0:
                    if i > 1: divs.append(i)
                    if x // i > 1: divs.append(x // i)
            divs = list(set(divs))
            mults = [i * x for i in range(1, M // x + 1)]
            all_y = divs + mults
            for y in all_y:
                if y == 1: continue
                if y == 2:
                    res = d[3] if 3 <= M else float('inf')
                else:
                    d_minus = d[y-1] if 2 <= y-1 <= M else float('inf')
                    d_plus = d[y+1] if 2 <= y+1 <= M else float('inf')
                    res = max(d_minus, d_plus)
                if res < min_max_d:
                    min_max_d = res
            new_d[x] = 1 + min_max_d
        d = new_d
    return max(d)

